sys_ws_operation.operation_script:
// RBAC Authorization Check
var __authorized = (function() {
  if (gs.hasRole("admin")) return true;
  var roles = "x_2056099_indust_0.production_planner,x_2056099_indust_0.production_manager,x_2056099_indust_0.production_supervisor,x_2056099_indust_0.operations_manager,x_2056099_indust_0.plant_manager,x_2056099_indust_0.warehouse_manager".split(",");
  for (var _i = 0; _i < roles.length; _i++) {
    if (gs.hasRole(roles[_i])) return true;
  }
  response.setStatus(403);
  response.setBody({error:"Unauthorized",message:"Insufficient role for simulation operations"});
  return false;
})();
if (!__authorized) { /* early exit */ }
else
(function process(request, response) {
    var orderSysId = request.queryParams.order_sys_id ?
        request.queryParams.order_sys_id.toString() : '';

    if (!orderSysId) {
        response.setStatus(400);
        response.setBody({
            result: { success: false, error: 'order_sys_id query parameter is required' }
        });
        return;
    }

    try {
        var sim = new x_2056099_indust_0.WarehouseSimulator();
        var result = sim.simulateFromOrder(orderSysId);
        response.setStatus(200);
        response.setBody({ result: result });
    } catch (e) {
        response.setStatus(500);
        response.setBody({
            result: { success: false, error: 'Simulation error: ' + e.message }
        });
    }
})(request, response);
